    if k[1] not in S: print('OB',k,v)
print(sum(1 for r in ob if not r['Client SKU']))
rc=list(csv.DictReader(open('3pl/receipts.csv')))
c=collections.Counter((r['Item Code'],r['Client SKU']) for r in rc)
for k,v in sorted(c.items()):
    if k[1] not in S: print('RC',k,v)
fi=list(csv.DictReader(open('amazon/fba_inventory.txt'),delimiter='\t'))
for r in fi: print(r['sku'],r['fnsku'],r['asin'],r['product-name'][:50], r['sku'] in S)
print(len({r['fnsku'] for r in fi}),len({r['asin'] for r in fi}))
