import pypdf,glob,re,collections,json
SUP={'MT':'NBBW','HT':'SZHT','LX':'YWLX','MJ':'FSMJ','QS':'NBQS','RF':'DGRF','TY':'HZTY','YD':'XMYD'}
out=collections.defaultdict(set)
for f in sorted(glob.glob('supplier_docs/CI-PL*.pdf')):
    pre=re.search(r'CI-PL_([A-Z]+)',f).group(1)
    t='\n'.join(p.extract_text() for p in pypdf.PdfReader(f).pages)
    L=t.split('\n')
    for i,l in enumerate(L):
        m=re.match(r'^([A-Z]{0,2}-?\d+) ([a-z].+)$',l)
        if m:
            hs=None
            for j in range(i+1,min(i+4,len(L))):
                h=re.match(r'^(\d{4}\.\d{2}\.\d{4}) ',L[j])
                if h: hs=h.group(1);break
            out[SUP[pre]+':'+m.group(1)].add((m.group(2).strip(),hs))
bad={k:v for k,v in out.items() if len(v)>1}
print(len(out),bad)
json.dump({k:sorted(v)[0] for k,v in out.items()},open('/private/tmp/claude-501/-private-var-folders-qj-j67my3-j6bzb4y5t82bvmkfh0000gn-T-m5-c-xa8fl84a-catalogue-work/f827615b-a19c-4199-9999-c92700ddc72b/scratchpad/items.json','w'),indent=0)
for k,v in sorted(out.items()): print(k,list(v)[0])
P=[json.loads(l) for l in open('shopify/products.jsonl')]
for p in P:
    print(p.get('title'),'|',p.get('vendor'),p.get('productType')) if 'sku' not in p else None
